import React, { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useLocation, useNavigate } from 'react-router-dom';
import { Typography, Stack, Button, TextField } from '@mui/material';
import { axios } from '../../utils/axios';
import TinyCmeEditor from "../../components/TinyCme/tinyEditor";
import { useMyContext } from "../provider";
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import GoBackButton from '../../components/goBackButton/GoBackButton';
import useResponsive from "../../hooks/useResponsive";

const TemplateForm = () => {
    const location = useLocation();
    const navigate = useNavigate();
    const { item } = location?.state || {};
    const [content, setContent] = useState(item ? item.body : '');
    const [key, setKey] = useState(item ? item?.key : '');
    const [title, setTitle] = useState(item ? item?.title : '');
    const { i18 } = useMyContext();
    const isMobile = useResponsive('down', 'sm');

    const backToUser = () => {
        navigate('/dashboard/pushNotification');
    };

    const handleEditorChange = (content) => {
        setContent(content);
    };

    const handleTemplateForm = async () => {
        try {
            const data = {
                key,
                title,
                body: content,
            };

            let res;

            if (item?._id) {
                // PUT request for update
                // res = await axios.put(`module/notifications/pushNotification/${item._id}`, data);
                res = await axios.put(`module/notifications/pushNotification`, {
                    templateId: item?._id,
                    ...data
                });
            } else {
                // POST request for create
                res = await axios.post('module/notifications/pushNotification', data);
            }

            if (res.status === 200 || res.status === 201) {
                GenerateToastConfig(res.data.message, 'success');
                navigate('/dashboard/pushNotification');
            } else {
                GenerateToastConfig(res.data.message);
            }
        } catch (err) {
            GenerateToastConfig(err?.response?.data?.message || 'Something went wrong');
        }
    };

    return (
        <div>
            <Helmet>
                <title>Push Notification Form</title>
            </Helmet>

            <Stack direction="row" alignItems="center" justifyContent="space-between" mb={5}>
                <Typography variant="h4" gutterBottom>
                    {item?.key?.toUpperCase() || 'Create Template'}
                </Typography>
                <GoBackButton
                    label={i18?.SETTINGSLIST?.GO_BACK || "Go Back"}
                    onClick={backToUser}
                    icon="icon-park-twotone:back"
                />
            </Stack>

            <div style={{ marginBottom: '20px' }}>
                <TextField
                    fullWidth
                    label={i18?.SETTINGSLIST?.KEY || "Key"}
                    variant="outlined"
                    value={key}
                    onChange={(e) => setKey(e.target.value)}
                />
            </div>

            <div style={{ marginBottom: '20px' }}>
                <TextField
                    fullWidth
                    label={i18?.SETTINGSLIST?.TITLE || "Title"}
                    variant="outlined"
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                />
            </div>

            <TinyCmeEditor value={content} onChange={handleEditorChange} />

            <div style={{ marginTop: '30px', display: 'flex', justifyContent: 'flex-end' }}>
                <Button
                    variant="contained"
                    onClick={handleTemplateForm}
                    disabled={!key.trim() || !title.trim() || !content.trim()}
                >
                    {i18?.SETTINGSLIST?.SUBMIT || "Submit"}
                </Button>
            </div>
        </div>
    );
};

export default TemplateForm;